import express, { type Express } from "express";
import cors from "cors";
import session from "express-session";
import connectPgSimple from "connect-pg-simple";
import pinoHttp from "pino-http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { existsSync } from "node:fs";
import { pool } from "@workspace/db";
import router from "./routes";
import { logger } from "./lib/logger";
import {
  helmetMiddleware,
  globalRateLimiter,
  ipBlockMiddleware,
  adminGeoMiddleware,
  adminRateLimiter,
  honeypotMiddleware,
} from "./middlewares/security";
import { subdomainMiddleware } from "./middlewares/subdomain";

const app: Express = express();

const isProd = process.env["NODE_ENV"] === "production";

// Trust reverse proxy — Plesk runs Nginx → Passenger → Node.js (2 layers).
// Setting true trusts all proxies, which is correct for a dedicated server.
if (isProd) {
  app.set("trust proxy", true);
}

// ── Security headers (helmet) ─────────────────────────────────────────────────
app.use(helmetMiddleware);

// ── CORS ─────────────────────────────────────────────────────────────────────
// Include drimpay.com (no subdomain) explicitly — the regex \.drimpay\.com$
// only matches subdomains, not the apex domain itself.
const extraOrigin = process.env["ALLOWED_ORIGIN"];
const allowedOrigins = isProd
  ? [
      "https://drimpay.com",
      "https://www.drimpay.com",
      ...(extraOrigin ? [extraOrigin] : []),
      /\.drimpay\.com$/,
      /\.replit\.app$/,
      /\.replit\.dev$/,
    ]
  : true;

app.use(
  cors({
    origin: allowedOrigins,
    credentials: true,
    methods: ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
    allowedHeaders: ["Content-Type", "Authorization", "X-Requested-With"],
  })
);

// ── Session ──────────────────────────────────────────────────────────────────
const sessionSecret = process.env["SESSION_SECRET"];
// Do NOT throw synchronously — a missing secret at startup would crash the
// Passenger process before it can even accept a health-check probe.
if (!sessionSecret) {
  logger.error("SESSION_SECRET is not set — sessions will not work. Set this env var in Plesk.");
}

const PgSession = connectPgSimple(session);

app.use(
  session({
    store: new PgSession({
      pool,
      tableName: "user_sessions",
      pruneSessionInterval: 60 * 15,
      // Auto-create the table if it doesn't exist yet (e.g. fresh Supabase instance)
      createTableIfMissing: true,
    }),
    // Fallback secret prevents a synchronous throw if env var is missing.
    // Sessions will be invalid but the process won't crash on Passenger.
    secret: sessionSecret || "drimpay-fallback-secret-please-set-SESSION_SECRET",
    resave: false,
    saveUninitialized: false,
    name: "dp_sid",
    cookie: {
      httpOnly: true,
      secure: isProd,
      // "lax" allows the cookie to be sent after redirects (e.g. login → dashboard).
      // "strict" blocks cookies on top-level navigations which causes auth loops on Plesk.
      sameSite: isProd ? "lax" : false,
      maxAge: 24 * 60 * 60 * 1000,
    },
  }),
);

// ── Logging ───────────────────────────────────────────────────────────────────
app.use(
  pinoHttp({
    logger,
    serializers: {
      req(req) {
        return {
          id: req.id,
          method: req.method,
          url: req.url?.split("?")[0],
        };
      },
      res(res) {
        return { statusCode: res.statusCode };
      },
    },
  }),
);

// ── Body parsers ──────────────────────────────────────────────────────────────
app.use(express.json({ limit: "2mb" }));
app.use(express.urlencoded({ extended: true, limit: "2mb" }));

// ── Quick health probe (before rate-limiter so Passenger/LB always reaches it) ──
app.get("/health", (_req, res) => {
  res.status(200).json({
    status: "ok",
    uptime: Math.floor(process.uptime()),
    memory: process.memoryUsage(),
    timestamp: new Date().toISOString(),
    env: process.env["NODE_ENV"] ?? "unknown",
  });
});

// ── Honeypot: trap scanner/bot probe paths before anything else ───────────────
app.use(honeypotMiddleware);

// ── Security middleware (IP block + global rate limit) ─────────────────────────
app.use(ipBlockMiddleware);
app.use(globalRateLimiter);

// ── Admin panel: rate limit + geo-restriction (Togo only by default) ──────────
// ADMIN_ALLOWED_COUNTRIES: comma-separated country codes (default: "TG")
// ADMIN_ALLOWED_IPS: comma-separated IP whitelist bypass
app.use("/api/admin", adminRateLimiter, adminGeoMiddleware);

// ── Subdomain routing (dashboard.drimpay.com → /dashboard, etc.) ─────────────
app.use(subdomainMiddleware);

// ── API routes ────────────────────────────────────────────────────────────────
app.use("/api", router);

// ── 404 handler for unmatched /api/* routes (must come before SPA fallback) ───
app.use("/api", (_req, res) => {
  res.status(404).json({ error: "Endpoint not found" });
});

// ── Serve React SPA whenever the built dist exists ────────────────────────────
// Intentionally NOT gated on isProd — we serve the frontend whenever the build
// artefact is present. This makes Plesk work correctly regardless of whether
// NODE_ENV is set, and keeps the dev workflow simple (build once, serve always).
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const frontendDist = path.resolve(__dirname, "../../drimpay/dist/public");
const indexHtml  = path.join(frontendDist, "index.html");

if (existsSync(frontendDist) && existsSync(indexHtml)) {
  // Static assets (JS, CSS, images) — aggressive caching except HTML
  app.use(
    express.static(frontendDist, {
      maxAge: "7d",
      etag: true,
      index: false, // Don't auto-serve index.html — let catch-all handle it
      setHeaders(res, filePath) {
        if (filePath.endsWith(".html")) {
          res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
        }
      },
    })
  );

  // SPA catch-all — MUST come after /api routes and static middleware.
  // Any URL that wasn't matched above (e.g. /dashboard, /fr/pricing on refresh)
  // receives index.html so React Router can handle client-side routing.
  app.use((_req, res) => {
    res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
    res.sendFile(indexHtml, (err) => {
      if (err && !res.headersSent) {
        res.status(500).json({ error: "Could not serve frontend" });
      }
    });
  });

  logger.info({ frontendDist }, "Serving frontend static files");
} else {
  logger.warn({ frontendDist }, "Frontend dist not found — API-only mode");
}

// ── Global Express error handler (MUST be last, after all routes) ─────────────
// 4-argument signature is required for Express to recognise this as an error handler
app.use((err: any, _req: any, res: any, _next: any) => {
  const status: number = typeof err?.status === "number" ? err.status : 500;
  const message: string = err?.message ?? "Erreur interne du serveur";
  logger.error({ err, status }, "Unhandled route error");
  if (!res.headersSent) {
    res.status(status).json({ error: message });
  }
});

export default app;
