// Reveal full API key — requires password confirmation
router.post("/dashboard/api-keys/:id/reveal", requireAuth, async (req, res) => {
  const userId = req.session.userId!;
  const keyId = parseInt(String(req.params.id));
  const { password } = req.body as { password?: string };

  if (!password) {
    res.status(400).json({ error: "Mot de passe requis" });
    return;
  }

  const [user] = await db
    .select({ passwordHash: usersTable.passwordHash })
    .from(usersTable)
    .where(eq(usersTable.id, userId));

  if (!user) { res.status(401).json({ error: "Non autorisé" }); return; }

  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) { res.status(401).json({ error: "Mot de passe incorrect" }); return; }

  const [key] = await db
    .select({ rawKey: apiKeysTable.rawKey, status: apiKeysTable.status })
    .from(apiKeysTable)
    .where(and(eq(apiKeysTable.id, keyId), eq(apiKeysTable.userId, userId)));

  if (!key) { res.status(404).json({ error: "Clé introuvable" }); return; }

  res.json({ rawKey: key.rawKey });
});

const createKeySchema = z.object({
  name: z.string().min(1).max(60),
  description: z.string().max(200).optional(),
  env: z.enum(["sandbox", "live"]),
});

router.post("/dashboard/api-keys", requireAuth, apiKeyRateLimiter, async (req, res) => {
  const parsed = createKeySchema.safeParse(req.body);
  if (!parsed.success) {
    res.status(400).json({ error: "Invalid input" });
    return;
  }

  const userId = req.session.userId!;
  const { name, description, env } = parsed.data;

  const rawKey = `dp_${env}_sk_${crypto.randomBytes(24).toString("hex")}`;
  const prefix = rawKey.substring(0, env === "sandbox" ? 16 : 12);
  const keyHash = await bcrypt.hash(rawKey, 10);

  const [key] = await db
    .insert(apiKeysTable)
    .values({ userId, name, description: description ?? null, keyHash, rawKey, prefix, env })
    .returning({
      id: apiKeysTable.id,
      name: apiKeysTable.name,
      description: apiKeysTable.description,
      prefix: apiKeysTable.prefix,
      rawKey: apiKeysTable.rawKey,
      env: apiKeysTable.env,
      status: apiKeysTable.status,
      createdAt: apiKeysTable.createdAt,
    });

  createNotification(
    userId, "info", "securite",
    `Nouvelle clé API créée — ${name}`,
    `Une clé API ${env === "sandbox" ? "Sandbox" : "Live"} nommée "${name}" a été générée. Conservez-la en lieu sûr.`,
    "/dashboard/api-keys",
  ).catch(() => {});
  res.status(201).json({ ...key, warning: "Store this key securely." });
});

router.delete("/dashboard/api-keys/:id", requireAuth, apiKeyRateLimiter, async (req, res) => {
  const userId = req.session.userId!;
  const keyId = parseInt(String(req.params.id));

  const [key] = await db
    .select()
    .from(apiKeysTable)
    .where(and(eq(apiKeysTable.id, keyId), eq(apiKeysTable.userId, userId)));

  if (!key) {
    res.status(404).json({ error: "API key not found" });
    return;
  }

  await db
    .update(apiKeysTable)
    .set({ status: "revoked" })
    .where(eq(apiKeysTable.id, keyId));

  createNotification(
    userId, "warning", "securite",
    `Clé API révoquée — ${key.name}`,
    `La clé API "${key.name}" (${key.prefix}...) a été révoquée et ne peut plus être utilisée.`,
    "/dashboard/api-keys",
  ).catch(() => {});
  res.json({ ok: true });
});

router.post("/dashboard/api-keys/regenerate", requireAuth, apiKeyRateLimiter, async (req, res) => {
  const userId = req.session.userId!;
  const { env, password } = req.body as { env: string; password?: string };

  if (!["sandbox", "live"].includes(env)) {
    res.status(400).json({ error: "Paramètres invalides" });
    return;
  }

  if (!password) {
    res.status(400).json({ error: "Mot de passe requis pour régénérer une clé" });
    return;
  }

  const [user] = await db
    .select({ passwordHash: usersTable.passwordHash })
    .from(usersTable)
    .where(eq(usersTable.id, userId));

  if (!user) { res.status(401).json({ error: "Non autorisé" }); return; }

  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) { res.status(401).json({ error: "Mot de passe incorrect" }); return; }

  // Revoke all existing active keys for this env
  await db
    .update(apiKeysTable)
    .set({ status: "revoked" })
    .where(and(eq(apiKeysTable.userId, userId), eq(apiKeysTable.env, env as any)));

  // Generate new unique key
  const rawKey = `dp_${env}_sk_${crypto.randomBytes(24).toString("hex")}`;
  const prefix = rawKey.substring(0, env === "sandbox" ? 16 : 12);
  const keyHash = await bcrypt.hash(rawKey, 10);
  const name = env === "sandbox" ? "Clé Sandbox" : "Clé Live";

  const [key] = await db
    .insert(apiKeysTable)
    .values({ userId, name, keyHash, rawKey, prefix, env: env as any })
    .returning({
      id: apiKeysTable.id,
      name: apiKeysTable.name,
      prefix: apiKeysTable.prefix,
      rawKey: apiKeysTable.rawKey,
      env: apiKeysTable.env,
      status: apiKeysTable.status,
      createdAt: apiKeysTable.createdAt,
    });

  createNotification(
    userId, "warning", "securite",
    `Clé ${env === "live" ? "Live" : "Sandbox"} régénérée`,
    `Votre clé API ${env === "live" ? "live" : "sandbox"} a été régénérée. L'ancienne clé a été révoquée.`,
    "/dashboard/api-keys",
  ).catch(() => {});

  res.status(201).json({ ...key, rawKey });
});

